#!/usr/bin/env bash
#
# Every name a browser might dial the management console by, computed from this
# host.
#
# Sourced, never executed. Defines FOYER_ADMIN_TLS_NAMES and exports it.
#
# ── why this file exists ─────────────────────────────────────────────────────
#
# The console's certificate is generated by the control plane, which derives its
# subjectAltNames from the machine it can see. Inside a container that is the
# *container's* hostname and the *container's* addresses — never the Docker
# host's. Those cover an SSH tunnel to 127.0.0.1, and nothing else.
#
# The console is published on the host's LAN address, and a certificate that
# omits that name is valid, well-formed, correctly generated, and refused by every
# browser on the one address anybody uses — with nothing going red anywhere.
#
# So the names are *declared* rather than derived, and this file is what declares
# them. An operator types no parameter — which is not the same as no parameter
# existing — so it is `hostname` that answers, never a human.
#
# ── why it is its own file ───────────────────────────────────────────────────
#
# `first-boot.sh` and `up.sh` both need it, and `up.sh` does not run
# `first-boot.sh`. A rule living in only one of them is a rule the upgrade path
# does not have — the same reason `secretdirs.sh` and `images.sh` are files.
#
# ── recomputed on every start, deliberately not stored ───────────────────────
#
# A host that changes address must pick the new one up, and freezing this into
# `foyer.env` would make the certificate right once. `internal/tlsca` replaces a
# stored certificate that does not cover a declared name — and leaves one that
# does entirely alone, so a stable address costs no rotation and a changed address
# costs exactly one.

# `die` if the sourcing script has one, a plain abort otherwise. Three scripts
# source this file and only two of them define `die`; a bare call would be an
# unbound-command failure with no sentence attached.
if ! declare -F die >/dev/null 2>&1; then
  die() { printf 'consolenames: %s\n' "$*" >&2; exit 1; }
fi

_foyer_console_names() {
  local names="" n label

  # Addresses first: this is what an operator dials.
  #
  # **Docker's own interfaces are excluded, and that is not tidiness.** `hostname -I`
  # includes every bridge gateway — `172.17.0.1`, and one per compose network — and
  # those subnets are recreated whenever somebody runs `docker compose down -v`. A
  # declared name that changes is a stored certificate that no longer covers it,
  # which `internal/tlsca` answers by regenerating: **a new fingerprint for the
  # operator to re-accept, every teardown.** That is precisely the churn the coverage
  # rule was written to avoid.
  #
  # Nothing is lost by excluding them. A bridge gateway is the host's side of a
  # container network; it is not an address an operator opens a browser on.
  #
  # By interface NAME rather than by address range: `172.16/12` is also legitimate
  # LAN space, and a venue on it would silently lose the only address that matters.
  if command -v ip >/dev/null 2>&1; then
    while read -r ifname addr; do
      case "${ifname}" in
        docker*|br-*|veth*|lo) continue ;;
      esac
      names="${names} ${addr%%/*}"
    done < <(ip -o -4 addr show 2>/dev/null | awk '{print $2, $4}')
  else
    # No `ip` — a macOS workstation running this for a syntax check, not a
    # deployment host. Fall back rather than declare nothing, and accept the
    # bridges: an install that cannot enumerate interfaces is better served by a
    # certificate with extra names than by one with none.
    for n in $(hostname -I 2>/dev/null || true); do
      names="${names} ${n}"
    done
  fi

  # Then the names. `.local` because Bonjour is how a laptop reaches a small box
  # on a venue LAN, and it is a name the machine may well answer to.
  for n in "$(hostname 2>/dev/null || true)" "$(hostname -f 2>/dev/null || true)"; do
    [[ -n "${n}" ]] || continue
    names="${names} ${n}"
    label="${n%%.*}"
    case "${n}" in
      *.local) ;;
      *) names="${names} ${label}.local" ;;
    esac
  done

  # One of each, in the order first seen.
  #
  # `internal/tlsca` de-duplicates too, so this is not what makes the certificate
  # correct — it is what makes the *declaration* readable. `hostname` and
  # `hostname -f` answer the same thing on a host with no domain, so the list would
  # go out as `foyer-host foyer-host.local foyer-host foyer-host.local`, and
  # `verify.sh` — which asserts one line per declared name — would print each of
  # them twice. A diagnostic that repeats itself is one an operator stops reading
  # closely.
  printf '%s' "${names}" | tr ' ' '\n' | awk 'NF && !seen[$0]++' | paste -sd' ' -
}

FOYER_ADMIN_TLS_NAMES="$(_foyer_console_names)"

# An empty list is a refusal, not a default.
#
# It means `hostname` answered nothing, and the console would then generate a
# certificate covering only what the container can see — which is the exact state
# this file exists to prevent, arriving silently. The symptom would be a browser
# refusing the name, which reads to an operator as a broken certificate rather
# than as an unset variable.
if [[ -z "${FOYER_ADMIN_TLS_NAMES}" ]]; then
  die "hostname produced no address and no name, so the console's certificate would cover nothing an operator can dial. Check \`hostname -I\` and \`hostname -f\` on this host."
fi

export FOYER_ADMIN_TLS_NAMES
